// QueryHandler is an implementation of the hub.v1.Query service.
type QueryHandler interface {
	// Params returns Hub parameters.
	Params(context.Context, *connect.Request[v1.QueryHubParamsRequest]) (*connect.Response[v1.QueryHubParamsResponse], error)
	// Beacon returns one verified beacon by height.
	Beacon(context.Context, *connect.Request[v1.QueryBeaconRequest]) (*connect.Response[v1.QueryBeaconResponse], error)
	// VrfKey returns one validator operator's active and pending VRF key.
	VrfKey(context.Context, *connect.Request[v1.QueryVrfKeyRequest]) (*connect.Response[v1.QueryVrfKeyResponse], error)
	// BuilderSet returns one builder set selected by exactly one stable selector.
	BuilderSet(context.Context, *connect.Request[v1.QueryBuilderSetRequest]) (*connect.Response[v1.QueryBuilderSetResponse], error)
	// Builder returns one builder identity.
	Builder(context.Context, *connect.Request[v1.QueryBuilderRequest]) (*connect.Response[v1.QueryBuilderResponse], error)
	// Builders pages the whole builder registry. It is the only way to enumerate
	// builders: Query/Builder needs an address the caller already knows, so
	// without this RPC a fresh client cannot discover one. V1 takes no status
	// selector because BuilderState has no status index (api_contract §16.3).
	// Builders executes the Builders operation.
	Builders(context.Context, *connect.Request[v1.QueryBuildersRequest]) (*connect.Response[v1.QueryBuildersResponse], error)
	// Fault returns one immutable role-fault attribution row.
	Fault(context.Context, *connect.Request[v1.QueryFaultRequest]) (*connect.Response[v1.QueryFaultResponse], error)
	// Earnings returns one address earnings ledger.
	Earnings(context.Context, *connect.Request[v1.QueryEarningsRequest]) (*connect.Response[v1.QueryEarningsResponse], error)
	// Model returns one registered model.
	Model(context.Context, *connect.Request[v1.QueryModelRequest]) (*connect.Response[v1.QueryModelResponse], error)
	// Models pages the whole model registry. It is the only way to enumerate
	// models: Query/Model needs a model_id the caller already knows, so without
	// this RPC a fresh client cannot discover one. V1 takes no status selector
	// because ModelState has no status index (api_contract §16.3).
	// Models executes the Models operation.
	Models(context.Context, *connect.Request[v1.QueryModelsRequest]) (*connect.Response[v1.QueryModelsResponse], error)
	// Profile returns one model profile.
	Profile(context.Context, *connect.Request[v1.QueryProfileRequest]) (*connect.Response[v1.QueryProfileResponse], error)
	// CortexNode returns one stable service identity.
	CortexNode(context.Context, *connect.Request[v1.QueryCortexNodeRequest]) (*connect.Response[v1.QueryCortexNodeResponse], error)
	// ServiceBond returns the node's single service bond and reserved liability.
	ServiceBond(context.Context, *connect.Request[v1.QueryServiceBondRequest]) (*connect.Response[v1.QueryServiceBondResponse], error)
	// ServiceUnbondings pages one operator's unbonding entries by status.
	ServiceUnbondings(context.Context, *connect.Request[v1.QueryServiceUnbondingsRequest]) (*connect.Response[v1.QueryServiceUnbondingsResponse], error)
	// CurrentServiceKey returns the sole current key binding for one operator,
	// including its ACTIVE or REVOKED lifecycle status.
	// CurrentServiceKey executes the CurrentServiceKey operation.
	CurrentServiceKey(context.Context, *connect.Request[v1.QueryCurrentServiceKeyRequest]) (*connect.Response[v1.QueryCurrentServiceKeyResponse], error)
	// ServiceDescriptor returns one current bounded service descriptor.
	ServiceDescriptor(context.Context, *connect.Request[v1.QueryServiceDescriptorRequest]) (*connect.Response[v1.QueryServiceDescriptorResponse], error)
	// ServiceLifecycle combines the identity and bond authorities of one operator.
	ServiceLifecycle(context.Context, *connect.Request[v1.QueryServiceLifecycleRequest]) (*connect.Response[v1.QueryServiceLifecycleResponse], error)
	// ProfileCapability returns one operator/profile capability row.
	ProfileCapability(context.Context, *connect.Request[v1.QueryProfileCapabilityRequest]) (*connect.Response[v1.QueryProfileCapabilityResponse], error)
	// ModelSupport returns one P30 support row.
	ModelSupport(context.Context, *connect.Request[v1.QueryModelSupportRequest]) (*connect.Response[v1.QueryModelSupportResponse], error)
	// DailySupport returns one operator/epoch heartbeat row.
	DailySupport(context.Context, *connect.Request[v1.QueryDailySupportRequest]) (*connect.Response[v1.QueryDailySupportResponse], error)
	// CurrentCandidatePool returns the single global pool the current pointer
	// resolves to (api_contract §16.3, empty request). Per-profile pools no longer
	// exist, so the old model_id/profile_version/duty path variables are gone.
	// CurrentCandidatePool executes the CurrentCandidatePool operation.
	CurrentCandidatePool(context.Context, *connect.Request[v1.QueryCurrentCandidatePoolRequest]) (*connect.Response[v1.QueryCurrentCandidatePoolResponse], error)
	// CandidatePoolSnapshot returns a retained snapshot header by immutable ID.
	CandidatePoolSnapshot(context.Context, *connect.Request[v1.QueryCandidatePoolSnapshotRequest]) (*connect.Response[v1.QueryCandidatePoolSnapshotResponse], error)
	// CandidatePoolMember returns one stable slot of one snapshot.
	CandidatePoolMember(context.Context, *connect.Request[v1.QueryCandidatePoolMemberRequest]) (*connect.Response[v1.QueryCandidatePoolMemberResponse], error)
	// CandidatePoolMembers pages one snapshot's members in slot order.
	CandidatePoolMembers(context.Context, *connect.Request[v1.QueryCandidatePoolMembersRequest]) (*connect.Response[v1.QueryCandidatePoolMembersResponse], error)
	// CompetitionEpoch returns one reward competition epoch.
	CompetitionEpoch(context.Context, *connect.Request[v1.QueryCompetitionEpochRequest]) (*connect.Response[v1.QueryCompetitionEpochResponse], error)
	// RewardEpochCursor returns bounded reward processing progress.
	RewardEpochCursor(context.Context, *connect.Request[v1.QueryRewardEpochCursorRequest]) (*connect.Response[v1.QueryRewardEpochCursorResponse], error)
	// RewardEpochAudit returns the immutable root retained after bounded prune.
	RewardEpochAudit(context.Context, *connect.Request[v1.QueryRewardEpochAuditRequest]) (*connect.Response[v1.QueryRewardEpochAuditResponse], error)
	// Treasury returns the single treasury row.
	Treasury(context.Context, *connect.Request[v1.QueryTreasuryRequest]) (*connect.Response[v1.QueryTreasuryResponse], error)
	// BridgeStatus returns the canonical route, controls, usage, supply, and live invariants.
	BridgeStatus(context.Context, *connect.Request[v1.QueryBridgeStatusRequest]) (*connect.Response[v1.QueryBridgeStatusResponse], error)
	// ValidatorBridgeSigner returns one validator's registered bridge signer.
	ValidatorBridgeSigner(context.Context, *connect.Request[v1.QueryValidatorBridgeSignerRequest]) (*connect.Response[v1.QueryValidatorBridgeSignerResponse], error)
	// FreezeSignal returns one retained freeze signal header.
	FreezeSignal(context.Context, *connect.Request[v1.QueryFreezeSignalRequest]) (*connect.Response[v1.QueryFreezeSignalResponse], error)
	// FreezeSignals pages one profile's freeze signals; status is a closed enum.
	FreezeSignals(context.Context, *connect.Request[v1.QueryFreezeSignalsRequest]) (*connect.Response[v1.QueryFreezeSignalsResponse], error)
	// EmergencyFreezeVotes lists votes for one signal.
	EmergencyFreezeVotes(context.Context, *connect.Request[v1.QueryEmergencyFreezeVotesRequest]) (*connect.Response[v1.QueryEmergencyFreezeVotesResponse], error)
	// TimeoutBucket returns an exact or effective timeout bucket. The RPC moved
	// here from task.v1.Query with the governance writer (§2.4).
	// TimeoutBucket executes the TimeoutBucket operation.
	TimeoutBucket(context.Context, *connect.Request[v1.QueryTimeoutBucketRequest]) (*connect.Response[v1.QueryTimeoutBucketResponse], error)
}

